/**
 * Semantic theming: one seed → the full OKLCH ramp (surfaces, borders, text,
 * accents, status, dark surfaces, metallics).
 *
 * This is the byte-identical TypeScript mirror of `crates/theme/src/semantic.rs`
 * (same formulas, same `color-mix(in oklch, …)` semantics: missing-hue carry,
 * shorter hue arc, premultiplied channel interpolation, same serialization).
 * The shared fixture `test/fixtures/semantic.json` — generated by the Rust
 * `dump-semantic` bin — pins both sides to identical output strings, so the
 * live preview and the API render from exactly the same palette.
 *
 * Every badge template references the ramp through `var(--vx-*, fallback)`
 * with the fallback baked at the default seed in light mode; `resolveRamp`
 * re-derives the whole vocabulary for any seed and mode.
 */

export const DEFAULT_SEED = "#3b82f6";

/** Below this chroma a hue is "missing" and carries over (CSS rule). */
const ACHROMATIC = 1e-6;

export interface Oklch {
  l: number;
  c: number;
  h: number;
}

export interface AlphaColor {
  color: Oklch;
  alpha: number;
}

const clamp01 = (v: number): number => Math.min(1, Math.max(0, v));

export function oklchFromRgb8(r: number, g: number, b: number): Oklch {
  const lin = (v: number) =>
    v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  const lr = lin(r / 255), lg = lin(g / 255), lb = lin(b / 255);
  const l_ = Math.cbrt(0.4122214708 * lr + 0.5363325363 * lg + 0.0514459929 * lb);
  const m_ = Math.cbrt(0.2119034982 * lr + 0.6806995451 * lg + 0.1073969566 * lb);
  const s_ = Math.cbrt(0.0883024619 * lr + 0.2817188376 * lg + 0.6299787005 * lb);
  const aOk = 1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_;
  const bOk = 0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_;
  const L = 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_;
  const c = Math.sqrt(aOk * aOk + bOk * bOk);
  let h = (Math.atan2(bOk, aOk) * 180) / Math.PI;
  if (h < 0) h += 360;
  return { l: L, c, h };
}

/** Parses `#rgb`, `#rrggbb`, or `oklch(L C H)` into OKLCH (null otherwise). */
export function parseOklchValue(input: string): Oklch | null {
  const v = input.trim();
  const hex = v.match(/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/);
  if (hex) {
    const h = hex[1];
    if (h.length === 3) {
      return oklchFromRgb8(
        parseInt(h[0] + h[0], 16),
        parseInt(h[1] + h[1], 16),
        parseInt(h[2] + h[2], 16),
      );
    }
    return oklchFromRgb8(
      parseInt(h.slice(0, 2), 16),
      parseInt(h.slice(2, 4), 16),
      parseInt(h.slice(4, 6), 16),
    );
  }
  const ok = v.match(/^oklch\(\s*([\d.]+)\s+([\d.]+)\s+([\d.]+)\s*\)$/);
  if (ok) return { l: +ok[1], c: +ok[2], h: +ok[3] };
  return null;
}

/**
 * Quantizes to a decimal grid so ulp-level libm differences between the
 * Rust and JavaScript engines cannot change the serialized output (mirrors
 * the Rust `q` helper exactly).
 */
const q = (v: number, digits: number): number => {
  const m = 10 ** digits;
  return Math.round(v * m) / m;
};

/** CSS `oklch()` string, or `oklch(L C H / A)` when translucent.
 * Components are first quantized to a 1e-10 grid (absorbing libm ulp noise
 * between the Rust and JS engines — interpolated hues can sit exactly on a
 * decimal rounding boundary), then formatted. */
export function alphaToCss({ color, alpha }: AlphaColor): string {
  const h = ((color.h % 360) + 360) % 360;
  const core = `${q(clamp01(color.l), 10).toFixed(4)} ${q(Math.max(0, color.c), 10).toFixed(4)} ${q(h, 10).toFixed(2)}`;
  return alpha >= 1 ? `oklch(${core})` : `oklch(${core} / ${q(clamp01(alpha), 10).toFixed(2)})`;
}

/**
 * `color-mix(in oklch, top pct%, base)` — premultiplied interpolation with
 * the CSS missing-hue and shorter-arc rules, in the same operation order as
 * the Rust implementation.
 */
export function colorMix(top: AlphaColor, base: AlphaColor, pct: number): AlphaColor {
  const w1 = Math.min(1, Math.max(0, pct / 100));
  const w2 = 1 - w1;

  let h1 = top.color.h;
  let h2 = base.color.h;
  const tAchromatic = top.color.c < ACHROMATIC || top.alpha <= 0;
  const bAchromatic = base.color.c < ACHROMATIC || base.alpha <= 0;
  if (tAchromatic && !bAchromatic) h1 = h2;
  else if (bAchromatic && !tAchromatic) h2 = h1;

  let delta = h2 - h1;
  if (delta > 180) delta -= 360;
  else if (delta < -180) delta += 360;
  const h = h1 + w2 * delta;

  const a = w1 * top.alpha + w2 * base.alpha;
  if (a <= 0) return { color: { l: 0, c: 0, h: 0 }, alpha: 0 };
  const chan = (t: number, b: number) => (w1 * top.alpha * t + w2 * base.alpha * b) / a;
  return {
    color: {
      l: chan(top.color.l, base.color.l),
      c: chan(Math.max(0, top.color.c), Math.max(0, base.color.c)),
      h,
    },
    alpha: a,
  };
}

const opaque = (color: Oklch): AlphaColor => ({ color, alpha: 1 });
const TRANSPARENT: AlphaColor = { color: { l: 0, c: 0, h: 0 }, alpha: 0 };

// ---------------------------------------------------------------------------
// The vocabulary — mirrors crates/theme/src/semantic.rs CORE / DARK_OVERRIDES.
// ---------------------------------------------------------------------------

