/** Mix formulas discovered in the badge CSS (written by the tokenizer). */
export interface MixFormula {
  token: string;
  pct: number;
  top: string; // "seed" | token name | "#hex"
  base: string; // token name | "#hex" | "transparent"
}

import mixesJson from "../../../crates/theme/assets/semantic-mixes.json";
export const MIXES: MixFormula[] = (mixesJson as { mixes: MixFormula[] }).mixes;

export type Mode = "light" | "dark";

export function parseSeed(value: string): Oklch | null {
  let v = value.trim();
  if (v.startsWith("#")) v = v.slice(1);
  if (v.length === 0 || v.length > 6 || !/^[0-9a-fA-F]+$/.test(v)) return null;
  let hex: string;
  if (v.length === 3) hex = v[0] + v[0] + v[1] + v[1] + v[2] + v[2];
  else if (v.length === 6) hex = v;
  else return null;
  return oklchFromRgb8(parseInt(hex.slice(0, 2), 16), parseInt(hex.slice(2, 4), 16), parseInt(hex.slice(4, 6), 16));
}

/** Named seed presets — the design source's swatch row (with v4 aliases). */
export const PRESET_SEEDS: ReadonlyArray<readonly [string, string]> = [
  ["blue", "#3b82f6"],
  ["violet", "#8b5cf6"],
  ["pink", "#ec4899"],
  ["red", "#ef4444"],
  ["amber", "#f59e0b"],
  ["green", "#22c55e"],
  ["teal", "#14b8a6"],
  ["slate", "#64748b"],
];

export const PRESET_ALIASES: ReadonlyArray<readonly [string, string]> = [
  ["rose", "pink"],
  ["emerald", "green"],
];

export function presetSeed(name: string): string | null {
  const canonical = PRESET_ALIASES.find(([alias]) => alias === name)?.[1] ?? name;
  return PRESET_SEEDS.find(([n]) => n === canonical)?.[1] ?? null;
}

function resolveComponent(component: string, seed: AlphaColor, tokens: Map<string, string>): AlphaColor {
  if (component === "seed") return seed;
  if (component === "transparent") return TRANSPARENT;
  if (component.startsWith("#")) {
    const parsed = parseOklchValue(component);
    if (!parsed) throw new Error(`mix component '${component}' does not parse`);
    return opaque(parsed);
  }
  const key = component.startsWith("vx-") ? component : `vx-${component}`;
  const value = tokens.get(key) ?? tokens.get(component);
  if (!value) throw new Error(`mix references unknown token '${component}'`);
  const parsed = parseOklchValue(value);
  if (!parsed) throw new Error(`resolved token '${key}' = '${value}' does not parse`);
  return opaque(parsed);
}

/** Resolves the full ramp for a seed and mode: core vocabulary + mix tokens. */
export function resolveRamp(seed: Oklch, mode: Mode): Record<string, string> {
  const seedAlpha = opaque(seed);
  const tokens = new Map<string, string>();
  const evalCore = (entries: ReadonlyArray<readonly [string, CoreFormula]>) => {
    for (const [token, formula] of entries) {
      if (formula.kind === "fixed") {
        tokens.set(token, alphaToCss(opaque(parseOklchValue(formula.hex)!)));
      } else {
        const base = opaque(parseOklchValue(formula.base)!);
        tokens.set(token, alphaToCss(colorMix(seedAlpha, base, formula.pct)));
      }
    }
  };
  evalCore(CORE);
  if (mode === "dark") evalCore(DARK_OVERRIDES);
  for (const formula of MIXES) {
    const top = resolveComponent(formula.top, seedAlpha, tokens);
    const base = resolveComponent(formula.base, seedAlpha, tokens);
    tokens.set(formula.token, alphaToCss(colorMix(top, base, formula.pct)));
  }
  return Object.fromEntries(tokens);
}

/**
 * Resolved-ramp cache keyed `seed|mode`. Every explorer card, preview and
 * picker swatch asks for the same (seed, mode) ramp dozens of times per
 * render — the OKLCH math (~50 color-mixes) must run once, not per card.
 */
const rampCache = new Map<string, Record<string, string>>();
const RAMP_CACHE_MAX = 512;

/** The ramp as a plain token map for CSS custom properties (`--vx-*`). */
export function semanticVars(seedHex: string, mode: Mode): Record<string, string> {
  const key = `${seedHex.trim().toLowerCase()}|${mode}`;
  const hit = rampCache.get(key);
  if (hit) return hit;
  const seed = parseSeed(seedHex);
  if (!seed) throw new Error(`invalid seed '${seedHex}'`);
  const ramp = resolveRamp(seed, mode);
  if (rampCache.size >= RAMP_CACHE_MAX) rampCache.clear();
  rampCache.set(key, ramp);
  return ramp;
}

/**
 * Resolved dual-ramp cache keyed `seed|valueSeed|mode` — same rationale as
 * `rampCache`, one slot per picker state instead of per card.
 */
const duoCache = new Map<string, Record<string, string>>();

/**
 * The base ramp PLUS the value-side `vx-v-*` token family, derived from
 * `valueSeedHex` (the base seed when null/undefined — mirroring the Rust
 * engine, which always overlays the family so the templates'
 * `var(--vx-v-*, fallback)` value-segment references resolve identically
 * with or without `?seed2=`).
 *
 * Keys keep the `vx-` convention: `vx-s-white` → `vx-v-s-white`. Byte-parity
 * with `overlay_value_seed` (crates/theme/src/semantic.rs).
 */
export function semanticVarsDuo(
  seedHex: string,
  valueSeedHex: string | null | undefined,
  mode: Mode,
): Record<string, string> {
  const seed = seedHex.trim().toLowerCase();
  const value = valueSeedHex ? valueSeedHex.trim().toLowerCase() : seed;
  const key = `${seed}|${value}|${mode}`;
  const hit = duoCache.get(key);
  if (hit) return hit;
  const base = semanticVars(seedHex, mode);
  const out: Record<string, string> = { ...base };
  const valueRamp = value === seed ? base : semanticVars(valueSeedHex as string, mode);
  for (const [token, css] of Object.entries(valueRamp)) {
    out[`vx-v-${token.slice(3)}`] = css;
  }
  if (duoCache.size >= RAMP_CACHE_MAX) duoCache.clear();
  duoCache.set(key, out);
  return out;
}
